typedef float vm_num_t;

class stringx
{
public:
  stringx operator+(const char*) const;
};

class script_object
{
public:
  class instance
  {
  public:
    const stringx& get_name() const;
  };
};

class vm_executable
{
public:
  const stringx& get_fullname() const;
};

class vm_thread
{
public:
  script_object::instance* get_instance() const;
  vm_executable* get_executable() const;
};

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
private:
  vm_thread* my_thread;
public:
  char* get_SP() const { return SP; }
  vm_thread* get_thread() const { return my_thread; }
  void pop(int n) { SP -= n; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

  protected:
    char* name;

  public:
    function(script_library_class*, const char*) {}
    virtual ~function() {}
    virtual bool operator()(vm_stack&, entry_t) { return true; }
  };
};

class bitmap_widget
{
public:
  virtual vm_num_t get_width() { return 1.0f; }
};

typedef bitmap_widget* vm_bitmap_widget_t;

void error(const stringx&);

class slf_bitmap_widget_get_width_t : public script_library_class::function
{
public:
  slf_bitmap_widget_get_width_t(script_library_class* slc,const char* n) : script_library_class::function(slc,n) {}
  struct parms_t
  {
    vm_bitmap_widget_t me;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vm_num_t result = parms->me->get_width();
    if (!stack.push((char*)&result,sizeof(result)) )
      error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() );
    return true;
  }
};

slf_bitmap_widget_get_width_t slf_bitmap_widget_get_width((script_library_class*)0,"get_width()");
